import {applyCustomTheme,mountCustomTheme} from './custom-theme.js';
import {defaultThemeCover} from './theme-covers.js';
import {escapeHTML as e} from './store.js';
export function initAppearance(state,{save,modal,field,onProfile,currentWorld=()=>state}){
 let syncCustom=()=>{};const apply=()=>{const appearance=currentWorld();document.body.dataset.typography=['editorial','literary','modern'].includes(appearance.typography)?appearance.typography:'editorial';document.body.dataset.palette=['sapphire','pond','aurora','custom'].includes(appearance.palette)?appearance.palette:'sapphire';document.body.classList.toggle('dark',appearance.theme==='dark');const cover=document.querySelector('.atelier-welcome-map[data-default-cover=true]');if(cover)cover.src=defaultThemeCover(appearance.palette);applyCustomTheme(appearance);};
 const trigger=document.querySelector('#themeButton');trigger.title='Personalizar tema';trigger.setAttribute('aria-label','Personalizar tema');const menu=document.createElement('div');menu.className='appearance-popover';menu.hidden=true;menu.innerHTML=`<span class="eyebrow">APARÊNCIA DO ATELIÊ</span><h2>Escolha sua atmosfera</h2><div class="theme-choices">${[['sapphire','Safira','Azul profundo e dourado',['#112250','#3C507D','#E0C58F','#F5F0E9']],['pond','Lago','Verdes, musgo e bege',['#0A3323','#839958','#F7F4D5','#D3968C']],['aurora','Aurora','Lilás, azul e tons suaves',['#B8D8E6','#CBB7E6','#F4A7C4','#F6F2E8']]].map(([id,name,desc,colors])=>`<button data-palette-choice="${id}" aria-pressed="false"><span class="theme-swatches">${colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span><span><strong>${name}</strong><small>${desc}</small></span><span class="theme-check">✓</span></button>`).join('')}</div><div class="font-picker"><span class="eyebrow">TIPOGRAFIA</span><div role="group" aria-label="Estilo de fontes"><button type="button" data-font-choice="editorial"><strong>Editorial</strong><small>Lora + Nunito Sans</small></button><button type="button" data-font-choice="literary"><strong>Literário</strong><small>Crimson Pro + Source Sans 3</small></button><button type="button" data-font-choice="modern"><strong>Contemporâneo</strong><small>Manrope</small></button></div></div><div class="appearance-modes"><button data-mode-choice="light">☼ Claro</button><button data-mode-choice="dark">☾ Escuro</button></div>`;document.querySelector('.top-actions').append(menu);
 function sync(){const appearance=currentWorld();syncCustom();menu.querySelectorAll('[data-font-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.fontChoice===(appearance.typography||'editorial'))));menu.querySelectorAll('[data-palette-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.paletteChoice===(appearance.palette||'sapphire'))));menu.querySelectorAll('[data-mode-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.modeChoice===(appearance.theme||'light'))));}trigger.onclick=()=>{menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));sync();};menu.querySelectorAll('[data-palette-choice]').forEach(b=>b.onclick=()=>{currentWorld().palette=b.dataset.paletteChoice;apply();sync();save();});menu.querySelectorAll('[data-mode-choice]').forEach(b=>b.onclick=()=>{currentWorld().theme=b.dataset.modeChoice;apply();sync();save();});document.addEventListener('click',ev=>{if(!menu.contains(ev.target)&&!trigger.contains(ev.target)){menu.hidden=true;trigger.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!menu.hidden){menu.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.focus();}});
 menu.querySelectorAll('[data-font-choice]').forEach(b=>b.onclick=()=>{currentWorld().typography=b.dataset.fontChoice;apply();sync();save();});syncCustom=mountCustomTheme(menu,currentWorld,save,apply,sync);apply();sync();return {apply,sync};
}
